using Agro360.Application.Contracts;
using Agro360.Domain.Operations;
using Agro360.Infrastructure.Persistence;
using Agro360.Multitenancy;
using Agro360.SharedKernel;
using Dapper;

namespace Agro360.Infrastructure.Services;

public sealed class WorkManagementService(DatabaseExecutor database,ITenantContext tenant):IWorkManagementService
{
 private Task<T> Tx<T>(Func<System.Data.Common.DbConnection,System.Data.Common.DbTransaction,Task<T>> work,CancellationToken ct)=>database.InTenantTransactionAsync(work,ct);
 public Task<IReadOnlyList<WorkLookup>> ActiveUsersAsync(string? search,CancellationToken ct)=>Tx(async(c,t)=>(IReadOnlyList<WorkLookup>)(await c.QueryAsync<WorkLookup>(new CommandDefinition("select id,name name from identity.users where tenant_id=@TenantId and status='ACTIVE' and (@Search is null or name ilike '%'||@Search||'%') order by name limit 50",new{tenant.TenantId,Search=string.IsNullOrWhiteSpace(search)?null:search.Trim()},t,cancellationToken:ct))).ToArray(),ct);
 public Task<PagedResult<OperationalTaskRow>> TasksAsync(string? search,string? status,string? priority,string? module,Guid? responsibleId,DateTimeOffset? from,DateTimeOffset? to,int page,int pageSize,CancellationToken ct)=>Tx(async(c,t)=>{page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var p=new{tenant.TenantId,Search=string.IsNullOrWhiteSpace(search)?null:search.Trim(),Status=status?.ToUpperInvariant(),Priority=priority?.ToUpperInvariant(),Module=module?.ToUpperInvariant(),ResponsibleId=responsibleId,From=from,To=to,Limit=pageSize,Offset=(page-1)*pageSize};const string where=" where x.tenant_id=@TenantId and x.deleted_at is null and (@Search is null or x.title ilike '%'||@Search||'%' or x.description ilike '%'||@Search||'%') and (@Status is null or (@Status='OVERDUE' and x.status not in ('COMPLETED','CANCELLED') and x.due_at<now()) or x.status=@Status) and (@Priority is null or x.priority=@Priority) and (@Module is null or x.module=@Module) and (@ResponsibleId is null or x.responsible_id=@ResponsibleId) and (@From is null or x.due_at>=@From) and (@To is null or x.due_at<=@To)";using var grid=await c.QueryMultipleAsync(new CommandDefinition("select count(*) from operations.operational_tasks x"+where+"; select x.id,x.title,x.description,u.name ResponsibleName,x.priority,case when x.status not in ('COMPLETED','CANCELLED') and x.due_at<now() then 'OVERDUE' else x.status end Status,x.due_at DueAt,x.module,x.entity_type EntityType,x.entity_id EntityId,x.created_at CreatedAt from operations.operational_tasks x join identity.users u on u.id=x.responsible_id and u.tenant_id=x.tenant_id"+where+" order by x.due_at limit @Limit offset @Offset",p,t,cancellationToken:ct));var total=await grid.ReadSingleAsync<long>();return new PagedResult<OperationalTaskRow>((await grid.ReadAsync<OperationalTaskRow>()).ToArray(),page,pageSize,total);},ct);
 public Task<Guid> CreateTaskAsync(TaskCommand x,CancellationToken ct){WorkManagementRules.ValidateTask(x.Title,x.ResponsibleId,x.DueAt,x.Priority);return Tx(async(c,t)=>{if(!await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from identity.users where id=@ResponsibleId and tenant_id=@TenantId and status='ACTIVE')",new{x.ResponsibleId,tenant.TenantId},t,cancellationToken:ct)))throw new DomainException("Responsável inativo ou inexistente.","task.responsible_inactive");var id=Guid.CreateVersion7();await c.ExecuteAsync(new CommandDefinition("insert into operations.operational_tasks(id,tenant_id,title,description,responsible_id,priority,due_at,module,entity_type,entity_id,created_by) values(@Id,@TenantId,@Title,@Description,@ResponsibleId,@Priority,@DueAt,@Module,@EntityType,@EntityId,@UserId);insert into operations.operational_task_events(id,tenant_id,task_id,event_type,notes,created_by) values(gen_random_uuid(),@TenantId,@Id,'CREATED','Tarefa criada',@UserId);insert into operations.notifications(id,tenant_id,user_id,type,module,severity,title,message,safe_link,created_by) values(gen_random_uuid(),@TenantId,@ResponsibleId,'TASK',@Module,@Severity,'Nova tarefa atribuída',@Title,'/Tasks/Details?id='||@Id,@UserId)",new{Id=id,tenant.TenantId,Title=x.Title.Trim(),Description=x.Description.Trim(),x.ResponsibleId,Priority=x.Priority.ToUpperInvariant(),x.DueAt,Module=x.Module.ToUpperInvariant(),x.EntityType,x.EntityId,tenant.UserId,Severity=x.Priority.ToUpperInvariant()},t,cancellationToken:ct));return id;},ct);}
 public Task ChangeTaskAsync(Guid id,TaskTransition x,CancellationToken ct){var status=x.Status.ToUpperInvariant();WorkManagementRules.ValidateTaskTransition(status,x.Reason);return database.InTenantTransactionAsync(async(c,t)=>{if(await c.ExecuteAsync(new CommandDefinition("update operations.operational_tasks set status=@Status,completion_description=case when @Status='COMPLETED' then @Reason end,cancellation_reason=case when @Status='CANCELLED' then @Reason end,completed_at=case when @Status='COMPLETED' then now() end,cancelled_at=case when @Status='CANCELLED' then now() end,updated_at=now(),updated_by=@UserId where id=@Id and tenant_id=@TenantId and deleted_at is null;insert into operations.operational_task_events(id,tenant_id,task_id,event_type,notes,created_by) select gen_random_uuid(),@TenantId,@Id,@Status,@Reason,@UserId where exists(select 1 from operations.operational_tasks where id=@Id and tenant_id=@TenantId)",new{Id=id,tenant.TenantId,Status=status,x.Reason,tenant.UserId},t,cancellationToken:ct))==0)throw new NotFoundException("Tarefa",id);},ct);}
 public Task<IReadOnlyList<TaskEventRow>> TaskHistoryAsync(Guid id,CancellationToken ct)=>Tx(async(c,t)=>(IReadOnlyList<TaskEventRow>)(await c.QueryAsync<TaskEventRow>(new CommandDefinition("select e.event_type EventType,e.notes,u.name ActorName,e.created_at CreatedAt from operations.operational_task_events e join identity.users u on u.id=e.created_by and u.tenant_id=e.tenant_id where e.tenant_id=@TenantId and e.task_id=@Id order by e.created_at desc",new{tenant.TenantId,Id=id},t,cancellationToken:ct))).ToArray(),ct);
 public Task<IReadOnlyList<AlertRow>> AlertsAsync(string? severity,string? status,string? module,CancellationToken ct)=>Tx(async(c,t)=>(IReadOnlyList<AlertRow>)(await c.QueryAsync<AlertRow>(new CommandDefinition("select id,title,description,severity,status,module,origin_type OriginType,origin_id OriginId,created_at CreatedAt,resolved_at ResolvedAt from operations.operational_alerts where tenant_id=@TenantId and (@Severity is null or severity=@Severity) and (@Status is null or status=@Status) and (@Module is null or module=@Module) order by case severity when 'CRITICAL' then 1 when 'HIGH' then 2 else 3 end,created_at desc limit 500",new{tenant.TenantId,Severity=severity?.ToUpperInvariant(),Status=status?.ToUpperInvariant(),Module=module?.ToUpperInvariant()},t,cancellationToken:ct))).ToArray(),ct);
 public Task ChangeAlertAsync(Guid id,string action,CancellationToken ct)=>database.InTenantTransactionAsync(async(c,t)=>{var status=action.ToLowerInvariant() switch{"read"=>"READ","resolve"=>"RESOLVED",_=>throw new DomainException("Ação de alerta inválida.","alert.action_invalid")};if(await c.ExecuteAsync(new CommandDefinition("update operations.operational_alerts set status=@Status,read_at=case when @Status='READ' then now() else read_at end,resolved_at=case when @Status='RESOLVED' then now() else resolved_at end,updated_at=now(),updated_by=@UserId where id=@Id and tenant_id=@TenantId;insert into operations.operational_alert_events(id,tenant_id,alert_id,event_type,created_by) select gen_random_uuid(),@TenantId,@Id,@Status,@UserId where exists(select 1 from operations.operational_alerts where id=@Id and tenant_id=@TenantId)",new{Id=id,tenant.TenantId,Status=status,tenant.UserId},t,cancellationToken:ct))==0)throw new NotFoundException("Alerta",id);},ct);
 public Task<int> EvaluateRulesAsync(CancellationToken ct)=>Tx(async(c,t)=>await c.ExecuteScalarAsync<int>(new CommandDefinition("select operations.evaluate_operational_rules(@TenantId,@UserId)",new{tenant.TenantId,tenant.UserId},t,cancellationToken:ct)),ct);
 public Task<IReadOnlyList<RuleRow>> RulesAsync(CancellationToken ct)=>Tx(async(c,t)=>(IReadOnlyList<RuleRow>)(await c.QueryAsync<RuleRow>(new CommandDefinition("select id,name,description,module,type,severity,action,active,last_executed_at LastExecutedAt from operations.operational_rules where tenant_id=@TenantId order by name",new{tenant.TenantId},t,cancellationToken:ct))).ToArray(),ct);
 public Task<Guid> SaveRuleAsync(Guid? id,RuleCommand x,CancellationToken ct)=>Tx(async(c,t)=>{if(string.IsNullOrWhiteSpace(x.Name)||string.IsNullOrWhiteSpace(x.ConditionJson)||!x.ConditionJson.TrimStart().StartsWith('{'))throw new DomainException("Nome e condição JSON válida são obrigatórios.","rule.invalid");var ruleId=id??Guid.CreateVersion7();await c.ExecuteAsync(new CommandDefinition("insert into operations.operational_rules(id,tenant_id,name,description,module,type,condition_json,severity,action,active,created_by) values(@Id,@TenantId,@Name,@Description,@Module,@Type,cast(@ConditionJson as jsonb),@Severity,@Action,@Active,@UserId) on conflict(tenant_id,id) do update set name=excluded.name,description=excluded.description,module=excluded.module,type=excluded.type,condition_json=excluded.condition_json,severity=excluded.severity,action=excluded.action,active=excluded.active,updated_at=now(),updated_by=@UserId",new{Id=ruleId,tenant.TenantId,x.Name,x.Description,Module=x.Module.ToUpperInvariant(),Type=x.Type.ToUpperInvariant(),x.ConditionJson,Severity=x.Severity.ToUpperInvariant(),Action=x.Action.ToUpperInvariant(),x.Active,tenant.UserId},t,cancellationToken:ct));return ruleId;},ct);
 public Task<IReadOnlyList<WorkflowRow>> WorkflowsAsync(string? status,string? module,CancellationToken ct)=>Tx(async(c,t)=>(IReadOnlyList<WorkflowRow>)(await c.QueryAsync<WorkflowRow>(new CommandDefinition("select w.id,d.name,d.module,w.entity_type EntityType,w.entity_id EntityId,w.status,r.name RequesterName,a.name ApproverName,w.opened_at OpenedAt,w.decided_at DecidedAt from operations.workflow_instances w join operations.workflow_definitions d on d.id=w.definition_id and d.tenant_id=w.tenant_id join identity.users r on r.id=w.requested_by and r.tenant_id=w.tenant_id join identity.users a on a.id=w.current_approver_id and a.tenant_id=w.tenant_id where w.tenant_id=@TenantId and (@Status is null or w.status=@Status) and (@Module is null or d.module=@Module) order by w.opened_at desc",new{tenant.TenantId,Status=status?.ToUpperInvariant(),Module=module?.ToUpperInvariant()},t,cancellationToken:ct))).ToArray(),ct);
 public Task<Guid> CreateWorkflowAsync(WorkflowCommand x,CancellationToken ct)=>Tx(async(c,t)=>{if(x.EntityId==Guid.Empty||x.ApproverId==Guid.Empty)throw new DomainException("Entidade e aprovador são obrigatórios.","workflow.invalid");var definition=await c.ExecuteScalarAsync<Guid?>(new CommandDefinition("select id from operations.workflow_definitions where tenant_id=@TenantId and name=@Name and active limit 1",new{tenant.TenantId,x.Name},t,cancellationToken:ct));if(definition is null){definition=Guid.CreateVersion7();await c.ExecuteAsync(new CommandDefinition("insert into operations.workflow_definitions(id,tenant_id,name,module,entity_type,segregation_required,created_by) values(@Id,@TenantId,@Name,@Module,@EntityType,@SegregationRequired,@UserId)",new{Id=definition,tenant.TenantId,x.Name,Module=x.Module.ToUpperInvariant(),x.EntityType,x.SegregationRequired,tenant.UserId},t,cancellationToken:ct));}var id=Guid.CreateVersion7();await c.ExecuteAsync(new CommandDefinition("insert into operations.workflow_instances(id,tenant_id,definition_id,entity_type,entity_id,status,requested_by,current_approver_id,opened_at,created_by) values(@Id,@TenantId,@Definition,@EntityType,@EntityId,'OPEN',@UserId,@ApproverId,now(),@UserId);insert into operations.notifications(id,tenant_id,user_id,type,module,severity,title,message,safe_link,created_by) values(gen_random_uuid(),@TenantId,@ApproverId,'APPROVAL',@Module,'HIGH','Aprovação pendente',@Name,'/Workflows/Details?id='||@Id,@UserId)",new{Id=id,tenant.TenantId,Definition=definition,x.EntityType,x.EntityId,tenant.UserId,x.ApproverId,Module=x.Module.ToUpperInvariant(),x.Name},t,cancellationToken:ct));return id;},ct);
 public Task DecideWorkflowAsync(Guid id,WorkflowDecisionCommand x,bool canApprove,CancellationToken ct){var decision=x.Decision.ToUpperInvariant();WorkManagementRules.ValidateDecision(decision,x.Comment);if(!canApprove)throw new DomainException("Usuário sem permissão para aprovar.","workflow.permission_denied");return database.InTenantTransactionAsync(async(c,t)=>{var item=await c.QuerySingleOrDefaultAsync<(Guid ApproverId,Guid RequesterId,bool Segregation)>(new CommandDefinition("select w.current_approver_id ApproverId,w.requested_by RequesterId,d.segregation_required Segregation from operations.workflow_instances w join operations.workflow_definitions d on d.id=w.definition_id and d.tenant_id=w.tenant_id where w.id=@Id and w.tenant_id=@TenantId and w.status in ('OPEN','IN_REVIEW') for update",new{Id=id,tenant.TenantId},t,cancellationToken:ct));if(item==default)throw new NotFoundException("Workflow",id);if(item.ApproverId!=tenant.UserId)throw new DomainException("Aprovação atribuída a outro usuário.","workflow.wrong_approver");if(item.Segregation&&item.RequesterId==tenant.UserId)throw new DomainException("Segregação impede autoaprovação.","workflow.self_approval");await c.ExecuteAsync(new CommandDefinition("update operations.workflow_instances set status=@Decision,decided_at=now(),decided_by=@UserId,updated_at=now(),updated_by=@UserId where id=@Id and tenant_id=@TenantId;insert into operations.workflow_decisions(id,tenant_id,instance_id,decision,comment,decided_by,decided_at,created_by) values(gen_random_uuid(),@TenantId,@Id,@Decision,@Comment,@UserId,now(),@UserId)",new{Id=id,tenant.TenantId,Decision=decision,x.Comment,tenant.UserId},t,cancellationToken:ct));},ct);}
 public Task<IReadOnlyList<NotificationRow>> NotificationsAsync(string? type,string? module,string? severity,DateTimeOffset? from,DateTimeOffset? to,CancellationToken ct)=>Tx(async(c,t)=>(IReadOnlyList<NotificationRow>)(await c.QueryAsync<NotificationRow>(new CommandDefinition("select id,type,module,severity,title,message,safe_link SafeLink,created_at CreatedAt,read_at ReadAt from operations.notifications where tenant_id=@TenantId and user_id=@UserId and (@Type is null or type=@Type) and (@Module is null or module=@Module) and (@Severity is null or severity=@Severity) and (@From is null or created_at>=@From) and (@To is null or created_at<=@To) order by created_at desc limit 500",new{tenant.TenantId,tenant.UserId,Type=type?.ToUpperInvariant(),Module=module?.ToUpperInvariant(),Severity=severity?.ToUpperInvariant(),From=from,To=to},t,cancellationToken:ct))).ToArray(),ct);
 public Task ReadNotificationAsync(Guid? id,CancellationToken ct)=>database.InTenantTransactionAsync(async(c,t)=>{await c.ExecuteAsync(new CommandDefinition("update operations.notifications set read_at=coalesce(read_at,now()),updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and user_id=@UserId and (@Id is null or id=@Id)",new{tenant.TenantId,tenant.UserId,Id=id},t,cancellationToken:ct));},ct);
 public Task<IReadOnlyList<CalendarRow>> CalendarAsync(DateTimeOffset from,DateTimeOffset to,string? module,Guid? responsibleId,string? priority,CancellationToken ct)=>Tx(async(c,t)=>(IReadOnlyList<CalendarRow>)(await c.QueryAsync<CalendarRow>(new CommandDefinition("select id,type,title,starts_at StartsAt,ends_at EndsAt,module,priority,safe_link SafeLink from operations.calendar_events where tenant_id=@TenantId and starts_at between @From and @To and (@Module is null or module=@Module) and (@ResponsibleId is null or responsible_id=@ResponsibleId) and (@Priority is null or priority=@Priority) order by starts_at",new{tenant.TenantId,From=from,To=to,Module=module?.ToUpperInvariant(),ResponsibleId=responsibleId,Priority=priority?.ToUpperInvariant()},t,cancellationToken:ct))).ToArray(),ct);
 public Task<IReadOnlyList<OutboxRow>> OutboxAsync(string? status,string? channel,CancellationToken ct)=>Tx(async(c,t)=>(IReadOnlyList<OutboxRow>)(await c.QueryAsync<OutboxRow>(new CommandDefinition("select id,channel,status,attempts,last_error LastError,created_at CreatedAt,processed_at ProcessedAt from operations.communication_outbox where tenant_id=@TenantId and (@Status is null or status=@Status) and (@Channel is null or channel=@Channel) order by created_at desc limit 500",new{tenant.TenantId,Status=status?.ToUpperInvariant(),Channel=channel?.ToUpperInvariant()},t,cancellationToken:ct))).ToArray(),ct);
 public Task<WorkDashboard> DashboardAsync(CancellationToken ct)=>Tx((c,t)=>c.QuerySingleAsync<WorkDashboard>(new CommandDefinition("select count(*) filter(where status not in('COMPLETED','CANCELLED')) OpenTasks,count(*) filter(where status not in('COMPLETED','CANCELLED') and due_at<now()) OverdueTasks,count(*) filter(where priority='CRITICAL' and status not in('COMPLETED','CANCELLED')) CriticalTasks,(select count(*) from operations.operational_alerts where tenant_id=@TenantId and severity='CRITICAL' and status<>'RESOLVED') CriticalAlerts,(select count(*) from operations.workflow_instances where tenant_id=@TenantId and status in('OPEN','IN_REVIEW')) PendingApprovals,(select count(*) from operations.notifications where tenant_id=@TenantId and user_id=@UserId and read_at is null) UnreadNotifications,(select count(*) from inventory.stock_balances where tenant_id=@TenantId and available<minimum) CriticalStocks,greatest(0,100-(count(*) filter(where status not in('COMPLETED','CANCELLED') and due_at<now())*5)::int-(select count(*)::int*10 from operations.operational_alerts where tenant_id=@TenantId and severity='CRITICAL' and status<>'RESOLVED')) HealthScore from operations.operational_tasks where tenant_id=@TenantId and deleted_at is null",new{tenant.TenantId,tenant.UserId},t,cancellationToken:ct)),ct);
}
